#[cfg(test)] mod tests { use std::sync::atomic::Ordering; use crate::reducer::{initial_lifecyclestate, reduce_lifecyclestate, LifecycleStateEvent, LifecycleStateMutable, LifecycleStateStatus}; #[test] fn matches_every_canonical_lifecycle_state() { let timeline: serde_json::Value = serde_json::from_str(include_str!("../../3_timeline.json")).unwrap(); let mut state = initial_lifecyclestate(); let mut states = Vec::new(); for event in timeline["events"].as_array().unwrap() { state = reduce_lifecyclestate(state, serde_json::from_value::<LifecycleStateEvent>(event.clone()).unwrap()); states.push(serde_json::to_value(&state).unwrap()); } assert_eq!(serde_json::Value::Array(states), timeline["states"]); let mutable = LifecycleStateMutable::new(); mutable.apply(LifecycleStateEvent::Loading); let first = mutable.state.get_cloned(); let second = mutable.state.get_cloned(); mutable.apply(LifecycleStateEvent::Finalize); assert_eq!(first.status, LifecycleStateStatus::Loading); assert_eq!(second.status, LifecycleStateStatus::Loading); assert_eq!(mutable.state.get_cloned().status, LifecycleStateStatus::Finalize); mutable.dispose(); assert_eq!(mutable.active.load(Ordering::SeqCst), 0); } }
